54	Piece::Piece() : index_(0), length_(0), nextBegin_(0), usedBySegment_(false) {}
55	
56	Piece::Piece(size_t index, int64_t length, int32_t blockLength)
57	    : bitfield_(make_unique<BitfieldMan>(blockLength, length)),
58	      index_(index),
59	      length_(length),
60	      nextBegin_(0),
61	      usedBySegment_(false)
62	{
63	}
64	
65	Piece::~Piece() = default;
66	
67	void Piece::completeBlock(size_t blockIndex)
68	{
69	  bitfield_->setBit(blockIndex);
70	  bitfield_->unsetUseBit(blockIndex);
71	}
72	
73	void Piece::clearAllBlock(WrDiskCache* diskCache)
74	{
75	  bitfield_->clearAllBit();
76	  bitfield_->clearAllUseBit();
77	  if (diskCache && wrCache_) {
78	    clearWrCache(diskCache);
79	  }
80	}
81	
82	void Piece::setAllBlock() { bitfield_->setAllBit(); }
83	
84	bool Piece::pieceComplete() const { return bitfield_->isAllBitSet(); }
85	
86	size_t Piece::countBlock() const { return bitfield_->countBlock(); }
87	
88	int32_t Piece::getBlockLength(size_t index) const
89	{
