105	bool Piece::isBlockUsed(size_t index) const
106	{
107	  return bitfield_->isUseBitSet(index);
108	}
109	
110	void Piece::cancelBlock(size_t blockIndex)
111	{
112	  bitfield_->unsetUseBit(blockIndex);
113	}
114	
115	size_t Piece::countCompleteBlock() const
116	{
117	  return bitfield_->countBlock() - bitfield_->countMissingBlock();
118	}
119	
120	size_t Piece::countMissingBlock() const
121	{
122	  return bitfield_->countMissingBlock();
123	}
