130	bool Piece::getMissingUnusedBlockIndex(size_t& index) const
131	{
132	  if (bitfield_->getFirstMissingUnusedIndex(index)) {
133	    bitfield_->setUseBit(index);
134	    return true;
135	  }
136	  else {
137	    return false;
138	  }
139	}
140	
141	size_t Piece::getMissingUnusedBlockIndex(std::vector<size_t>& indexes,
142	                                         size_t n) const
143	{
144	  size_t num = bitfield_->getFirstNMissingUnusedIndex(indexes, n);
145	  if (num) {
146	    for (std::vector<size_t>::const_iterator i = indexes.end() - num,
147	                                             eoi = indexes.end();
148	         i != eoi; ++i) {
149	      bitfield_->setUseBit(*i);
150	    }
151	  }
152	  return num;
153	}
154	
155	bool Piece::getFirstMissingBlockIndexWithoutLock(size_t& index) const
156	{
157	  return bitfield_->getFirstMissingIndex(index);
158	}
