119	std::shared_ptr<Piece> DefaultPieceStorage::checkOutPiece(size_t index,
120	                                                          cuid_t cuid)
121	{
122	  assert(!bitfieldMan_->isFilterEnabled() ||
123	         bitfieldMan_->isFilterBitSet(index));
124	
125	  bitfieldMan_->setUseBit(index);
126	
127	  std::shared_ptr<Piece> piece = findUsedPiece(index);
128	  if (!piece) {
129	    piece = std::make_shared<Piece>(index, bitfieldMan_->getBlockLength(index));
130	    piece->setHashType(downloadContext_->getPieceHashType());
131	
132	    addUsedPiece(piece);
133	  }
134	  piece->addUser(cuid);
135	  RequestGroup* group = downloadContext_->getOwnerRequestGroup();
136	  if ((!group || !group->inMemoryDownload()) && wrDiskCache_ &&
137	      !piece->getWrDiskCacheEntry()) {
138	    // So, we rely on the fact that diskAdaptor_ is not reinitialized
139	    // in the session.
140	    piece->initWrCache(wrDiskCache_, diskAdaptor_);
141	  }
142	  return piece;
143	}
