195	void DefaultPieceStorage::getMissingPiece(
196	    std::vector<std::shared_ptr<Piece>>& pieces, size_t minMissingBlocks,
197	    const unsigned char* bitfield, size_t length, cuid_t cuid)
198	{
199	  const size_t mislen = bitfieldMan_->getBitfieldLength();
200	  auto misbitfield = make_unique<unsigned char[]>(mislen);
201	  size_t blocks = bitfieldMan_->countBlock();
202	  size_t misBlock = 0;
203	  if (isEndGame()) {
204	    bool r = bitfieldMan_->getAllMissingIndexes(misbitfield.get(), mislen,
205	                                                bitfield, length);
206	    if (!r) {
207	      return;
208	    }
209	    std::vector<size_t> indexes;
210	    for (size_t i = 0; i < blocks; ++i) {
211	      if (bitfield::test(misbitfield, blocks, i)) {
212	        indexes.push_back(i);
213	      }
214	    }
215	    std::shuffle(indexes.begin(), indexes.end(),
216	                 *SimpleRandomizer::getInstance());
217	    for (std::vector<size_t>::const_iterator i = indexes.begin(),
218	                                             eoi = indexes.end();
219	         i != eoi && misBlock < minMissingBlocks; ++i) {
220	      std::shared_ptr<Piece> piece = checkOutPiece(*i, cuid);
221	      if (piece->getUsedBySegment()) {
222	        // We don't share piece downloaded via HTTP/FTP
223	        piece->removeUser(cuid);
224	      }
225	      else {
226	        pieces.push_back(piece);
227	        misBlock += piece->countMissingBlock();
228	      }
229	    }
230	  }
231	  else {
232	    bool r = bitfieldMan_->getAllMissingUnusedIndexes(misbitfield.get(), mislen,
233	                                                      bitfield, length);
234	    if (!r) {
235	      return;
236	    }
237	    while (misBlock < minMissingBlocks) {
238	      size_t index;
239	      if (pieceSelector_->select(index, misbitfield.get(), blocks)) {
240	        pieces.push_back(checkOutPiece(index, cuid));
241	        bitfield::flipBit(misbitfield.get(), blocks, index);
242	        misBlock += pieces.back()->countMissingBlock();
243	      }
244	      else {
245	        break;
246	      }
247	    }
248	  }
249	}
