593	// not unittested
594	void DefaultPieceStorage::setupFileFilter()
595	{
596	  const std::vector<std::shared_ptr<FileEntry>>& fileEntries =
597	      downloadContext_->getFileEntries();
598	  bool allSelected = true;
599	  for (auto& e : fileEntries) {
600	    if (!e->isRequested()) {
601	      allSelected = false;
602	      break;
603	    }
604	  }
605	  if (allSelected) {
606	    return;
607	  }
608	  for (auto& e : fileEntries) {
609	    if (e->isRequested()) {
610	      bitfieldMan_->addFilter(e->getOffset(), e->getLength());
611	    }
612	  }
613	  bitfieldMan_->enableFilter();
614	}
