633	// not unittested
634	void DefaultPieceStorage::initStorage()
635	{
636	  if (downloadContext_->getFileEntries().size() == 1) {
637	    A2_LOG_DEBUG("Instantiating DirectDiskAdaptor");
638	    auto directDiskAdaptor = std::make_shared<DirectDiskAdaptor>();
639	    directDiskAdaptor->setTotalLength(downloadContext_->getTotalLength());
640	    directDiskAdaptor->setFileEntries(
641	        downloadContext_->getFileEntries().begin(),
642	        downloadContext_->getFileEntries().end());
643	
644	    directDiskAdaptor->setDiskWriter(
645	        diskWriterFactory_->newDiskWriter(directDiskAdaptor->getFilePath()));
646	    diskAdaptor_ = std::move(directDiskAdaptor);
647	  }
648	  else {
649	    A2_LOG_DEBUG("Instantiating MultiDiskAdaptor");
650	    auto multiDiskAdaptor = std::make_shared<MultiDiskAdaptor>();
651	    multiDiskAdaptor->setFileEntries(downloadContext_->getFileEntries().begin(),
652	                                     downloadContext_->getFileEntries().end());
653	    multiDiskAdaptor->setPieceLength(downloadContext_->getPieceLength());
654	    diskAdaptor_ = std::move(multiDiskAdaptor);
655	  }
656	  if (option_->get(PREF_FILE_ALLOCATION) == V_FALLOC) {
657	    diskAdaptor_->setFileAllocationMethod(DiskAdaptor::FILE_ALLOC_FALLOC);
658	  }
659	  else if (option_->get(PREF_FILE_ALLOCATION) == V_TRUNC) {
660	    diskAdaptor_->setFileAllocationMethod(DiskAdaptor::FILE_ALLOC_TRUNC);
661	  }
662	}
