690	  if (!wrDiskCache_) {
691	    return;
692	  }
693	  // UsedPieceSet is sorted by piece index. It means we can flush
694	  // cache by non-decreasing offset, which is good to reduce disk seek
695	  // unless the file is heavily fragmented.
696	  for (auto& piece : usedPieces_) {
697	    auto ce = piece->getWrDiskCacheEntry();
698	    if (ce) {
699	      piece->flushWrCache(wrDiskCache_);
700	      if (releaseEntries) {
701	        piece->releaseWrCache(wrDiskCache_);
702	      }
703	    }
704	  }
705	}
706	
707	int32_t DefaultPieceStorage::getPieceLength(size_t index)
708	{
709	  return bitfieldMan_->getBlockLength(index);
710	}
711	
712	void DefaultPieceStorage::advertisePiece(cuid_t cuid, size_t index,
713	                                         Timer registeredTime)
714	{
715	  haves_.emplace_back(nextHaveIndex_++, cuid, index, std::move(registeredTime));
716	}
717	
718	uint64_t DefaultPieceStorage::getAdvertisedPieceIndexes(
719	    std::vector<size_t>& indexes, cuid_t myCuid, uint64_t lastHaveIndex)
720	{
721	  auto it =
722	      std::upper_bound(std::begin(haves_), std::end(haves_), lastHaveIndex,
723	                       [](uint64_t lastHaveIndex, const HaveEntry& have) {
724	                         return lastHaveIndex < have.haveIndex;
725	                       });
726	
727	  if (it == std::end(haves_)) {
728	    return lastHaveIndex;
729	  }
730	
731	  for (; it != std::end(haves_); ++it) {
732	    indexes.push_back((*it).index);
733	  }
734	
735	  return (*(std::end(haves_) - 1)).haveIndex;
736	}
737	
738	void DefaultPieceStorage::removeAdvertisedPiece(const Timer& expiry)
739	{
740	  auto it = std::upper_bound(std::begin(haves_), std::end(haves_), expiry,
741	                             [](const Timer& expiry, const HaveEntry& have) {
742	                               return expiry < have.registeredTime;
743	                             });
744	
745	  A2_LOG_DEBUG(
746	      fmt(MSG_REMOVED_HAVE_ENTRY,
747	          static_cast<unsigned long>(std::distance(std::begin(haves_), it))));
748	
749	  haves_.erase(std::begin(haves_), it);
750	}
751	
752	void DefaultPieceStorage::markAllPiecesDone() { bitfieldMan_->setAllBit(); }
753	
754	void DefaultPieceStorage::markPiecesDone(int64_t length)
755	{
756	  if (length == bitfieldMan_->getTotalLength()) {
757	    bitfieldMan_->setAllBit();
758	  }
759	  else if (length == 0) {
760	    // TODO this would go to markAllPiecesUndone()
761	    bitfieldMan_->clearAllBit();
762	    usedPieces_.clear();
763	  }
764	  else {
765	    size_t numPiece = length / bitfieldMan_->getBlockLength();
766	    if (numPiece > 0) {
767	      bitfieldMan_->setBitRange(0, numPiece - 1);
768	    }
769	    size_t r = (length % bitfieldMan_->getBlockLength()) / Piece::BLOCK_LENGTH;
770	    if (r > 0) {
771	      auto p = std::make_shared<Piece>(numPiece,
772	                                       bitfieldMan_->getBlockLength(numPiece));
773	
774	      for (size_t i = 0; i < r; ++i) {
775	        p->completeBlock(i);
776	      }
777	
778	      p->setHashType(downloadContext_->getPieceHashType());
779	
780	      addUsedPiece(p);
781	    }
782	  }
783	}
784	
785	void DefaultPieceStorage::markPieceMissing(size_t index)
786	{
787	  bitfieldMan_->unsetBit(index);
788	}
789	
790	void DefaultPieceStorage::addInFlightPiece(
791	    const std::vector<std::shared_ptr<Piece>>& pieces)
792	{
793	  usedPieces_.insert(pieces.begin(), pieces.end());
794	}
795	
796	size_t DefaultPieceStorage::countInFlightPiece() { return usedPieces_.size(); }
797	
798	void DefaultPieceStorage::getInFlightPieces(
799	    std::vector<std::shared_ptr<Piece>>& pieces)
800	{
801	  pieces.insert(pieces.end(), usedPieces_.begin(), usedPieces_.end());
802	}
803	
804	void DefaultPieceStorage::setDiskWriterFactory(
805	    const std::shared_ptr<DiskWriterFactory>& diskWriterFactory)
806	{
807	  diskWriterFactory_ = diskWriterFactory;
808	}
