834	size_t DefaultPieceStorage::getNextUsedIndex(size_t index)
835	{
836	  for (size_t i = index + 1; i < bitfieldMan_->countBlock(); ++i) {
837	    if (bitfieldMan_->isUseBitSet(i) || bitfieldMan_->isBitSet(i)) {
838	      return i;
839	    }
