216	template <typename Array>
217	size_t getStartIndex(size_t index, const Array& bitfield, size_t blocks)
218	{
219	  while (index < blocks && bitfield::test(bitfield, blocks, index)) {
220	    ++index;
221	  }
222	  if (blocks <= index) {
223	    return blocks;
224	  }
225	  else {
226	    return index;
227	  }
228	}
