242	namespace {
243	template <typename Array>
244	bool getSparseMissingUnusedIndex(size_t& index, int32_t minSplitSize,
245	                                 const Array& bitfield,
246	                                 const unsigned char* useBitfield,
247	                                 int32_t blockLength, size_t blocks)
248	{
249	  BitfieldMan::Range maxRange;
250	  BitfieldMan::Range currentRange;
251	  size_t nextIndex = 0;
252	  while (nextIndex < blocks) {
253	    currentRange.startIndex = getStartIndex(nextIndex, bitfield, blocks);
254	    if (currentRange.startIndex == blocks) {
255	      break;
256	    }
257	    currentRange.endIndex =
258	        getEndIndex(currentRange.startIndex, bitfield, blocks);
259	
260	    if (currentRange.startIndex > 0) {
261	      if (bitfield::test(useBitfield, blocks, currentRange.startIndex - 1)) {
262	        currentRange.startIndex = currentRange.getMidIndex();
263	      }
264	    }
265	    // If range is equal, choose a range where its startIndex-1 is
266	    // set.
267	    if (maxRange < currentRange ||
268	        (maxRange == currentRange && maxRange.startIndex > 0 &&
269	         currentRange.startIndex > 0 &&
270	         (!bitfield::test(bitfield, blocks, maxRange.startIndex - 1) ||
271	          bitfield::test(useBitfield, blocks, maxRange.startIndex - 1)) &&
272	         bitfield::test(bitfield, blocks, currentRange.startIndex - 1) &&
273	         !bitfield::test(useBitfield, blocks, currentRange.startIndex - 1))) {
274	      maxRange = currentRange;
275	    }
276	    nextIndex = currentRange.endIndex;
277	  }
278	  if (maxRange.getSize()) {
279	    if (maxRange.startIndex == 0) {
280	      index = 0;
281	      return true;
282	    }
283	    else {
284	      if ((!bitfield::test(useBitfield, blocks, maxRange.startIndex - 1) &&
285	           bitfield::test(bitfield, blocks, maxRange.startIndex - 1)) ||
286	          (static_cast<int64_t>(maxRange.endIndex - maxRange.startIndex) *
287	               blockLength >=
288	           minSplitSize)) {
289	        index = maxRange.startIndex;
290	        return true;
291	      }
292	      else {
293	        return false;
294	      }
295	    }
296	  }
297	  else {
298	    return false;
299	  }
300	}
