322	namespace {
323	template <typename Array>
324	bool getGeomMissingUnusedIndex(size_t& index, int32_t minSplitSize,
325	                               const Array& bitfield,
326	                               const unsigned char* useBitfield,
327	                               int32_t blockLength, size_t blocks, double base,
328	                               size_t offsetIndex)
329	{
330	  double start = 0;
331	  double end = 1;
332	  while (start + offsetIndex < blocks) {
333	    index = blocks;
334	    for (size_t i = start + offsetIndex,
335	                eoi = std::min(blocks, static_cast<size_t>(end + offsetIndex));
336	         i < eoi; ++i) {
337	      if (bitfield::test(useBitfield, blocks, i)) {
338	        break;
339	      }
340	      else if (!bitfield::test(bitfield, blocks, i)) {
341	        index = i;
342	        break;
343	      }
344	    }
345	    if (index < blocks) {
346	      return true;
347	    }
348	    else {
349	      start = end;
350	      end *= base;
351	    }
352	  }
353	  return getSparseMissingUnusedIndex(index, minSplitSize, bitfield, useBitfield,
354	                                     blockLength, blocks);
355	}
