379	namespace {
380	template <typename Array>
381	bool getInorderMissingUnusedIndex(size_t& index, size_t startIndex,
382	                                  size_t lastIndex, int32_t minSplitSize,
383	                                  const Array& bitfield,
384	                                  const unsigned char* useBitfield,
385	                                  int32_t blockLength, size_t blocks)
386	{
387	  // We always return first piece if it is available.
388	  if (!bitfield::test(bitfield, blocks, startIndex) &&
389	      !bitfield::test(useBitfield, blocks, startIndex)) {
390	    index = startIndex;
391	    return true;
392	  }
393	  for (size_t i = startIndex + 1; i < lastIndex;) {
394	    if (!bitfield::test(bitfield, blocks, i) &&
395	        !bitfield::test(useBitfield, blocks, i)) {
396	      // If previous piece has already been retrieved, we can download
397	      // from this index.
398	      if (!bitfield::test(useBitfield, blocks, i - 1) &&
399	          bitfield::test(bitfield, blocks, i - 1)) {
400	        index = i;
401	        return true;
402	      }
403	      // Check free space of minSplitSize.  When checking this, we use
404	      // blocks instead of lastIndex.
405	      size_t j;
406	      for (j = i; j < blocks; ++j) {
407	        if (bitfield::test(bitfield, blocks, j) ||
408	            bitfield::test(useBitfield, blocks, j)) {
409	          break;
410	        }
411	        if (static_cast<int64_t>(j - i + 1) * blockLength >= minSplitSize) {
412	          index = j;
413	          return true;
414	        }
415	      }
416	      i = j + 1;
417	    }
418	    else {
419	      ++i;
420	    }
421	  }
422	  return false;
423	}
