744	    size_t startBlock = offset / blockLength_;
745	    if (blocks_ <= startBlock) {
746	      startBlock = blocks_;
747	    }
748	    size_t endBlock = (offset + length - 1) / blockLength_;
749	    for (size_t i = 0; i < startBlock; ++i) {
750	      setFilterBit(i);
