782	int64_t BitfieldMan::getFilteredTotalLengthNow() const
783	{
784	  if (!filterBitfield_) {
785	    return 0;
786	  }
787	  size_t filteredBlocks = bitfield::countSetBit(filterBitfield_, blocks_);
788	  if (filteredBlocks == 0) {
789	    return 0;
790	  }
791	  if (bitfield::test(filterBitfield_, blocks_, blocks_ - 1)) {
792	    return ((int64_t)filteredBlocks - 1) * blockLength_ + getLastBlockLength();
793	  }
794	  else {
795	    return ((int64_t)filteredBlocks) * blockLength_;
796	  }
