799	namespace {
800	template <typename Array, typename CountFun>
801	int64_t computeCompletedLength(const Array& bitfield, const BitfieldMan* btman,
802	                               CountFun cntfun)
803	{
804	  size_t nbits = btman->countBlock();
805	  size_t completedBlocks = cntfun(bitfield, nbits);
806	  int64_t completedLength = 0;
807	  if (completedBlocks == 0) {
808	    completedLength = 0;
809	  }
810	  else {
811	    if (bitfield::test(bitfield, nbits, nbits - 1)) {
812	      completedLength =
813	          ((int64_t)completedBlocks - 1) * btman->getBlockLength() +
814	          btman->getLastBlockLength();
815	    }
816	    else {
817	      completedLength = ((int64_t)completedBlocks) * btman->getBlockLength();
818	    }
819	  }
820	  return completedLength;
821	}
822	} // namespace
