824	int64_t BitfieldMan::getCompletedLength(bool useFilter) const
825	{
826	  if (useFilter && filterEnabled_) {
827	    auto arr = array(bitfield_) & array(filterBitfield_);
828	    return computeCompletedLength(arr, this,
829	                                  &bitfield::countSetBitSlow<decltype(arr)>);
830	  }
831	  else {
832	    return computeCompletedLength(bitfield_, this, &bitfield::countSetBit);
833	  }
