881	bool BitfieldMan::isBitSetOffsetRange(int64_t offset, int64_t length) const
882	{
883	  if (length <= 0) {
884	    return false;
885	  }
886	  if (totalLength_ <= offset) {
887	    return false;
888	  }
889	  if (totalLength_ < offset + length) {
890	    length = totalLength_ - offset;
891	  }
892	  size_t startBlock = offset / blockLength_;
893	  size_t endBlock = (offset + length - 1) / blockLength_;
894	  for (size_t i = startBlock; i <= endBlock; i++) {
895	    if (!isBitSet(i)) {
896	      return false;
897	    }
898	  }
899	  return true;
900	}
901	
902	int64_t BitfieldMan::getOffsetCompletedLength(int64_t offset,
903	                                              int64_t length) const
904	{
905	  int64_t res = 0;
906	  if (length == 0 || totalLength_ <= offset) {
907	    return 0;
908	  }
909	  if (totalLength_ < offset + length) {
910	    length = totalLength_ - offset;
911	  }
912	  size_t start = offset / blockLength_;
913	  size_t end = (offset + length - 1) / blockLength_;
914	  if (start == end) {
915	    if (isBitSet(start)) {
916	      res = length;
917	    }
918	  }
919	  else {
920	    if (isBitSet(start)) {
921	      res += static_cast<int64_t>(start + 1) * blockLength_ - offset;
922	    }
923	    for (size_t i = start + 1; i <= end - 1; ++i) {
924	      if (isBitSet(i)) {
925	        res += blockLength_;
926	      }
927	    }
928	    if (isBitSet(end)) {
929	      res += offset + length - static_cast<int64_t>(end) * blockLength_;
930	    }
931	  }
932	  return res;
933	}
934	
935	int64_t BitfieldMan::getMissingUnusedLength(size_t startingIndex) const
936	{
937	  if (blocks_ <= startingIndex) {
938	    return 0;
939	  }
940	  int64_t length = 0;
941	  for (size_t i = startingIndex; i < blocks_; ++i) {
942	    if (isBitSet(i) || isUseBitSet(i)) {
943	      break;
944	    }
945	    length += getBlockLength(i);
946	  }
947	  return length;
948	}
