                       const unsigned char* data, size_t len);
  void releaseWrCache(WrDiskCache* diskCache);
  WrDiskCacheEntry* getWrDiskCacheEntry() const { return wrCache_.get(); }
};

} // namespace aria2

#endif // D_PIECE_H

