289	                   static_cast<unsigned long>(segment->getIndex())));
290	  const std::shared_ptr<Piece>& piece = segment->getPiece();
291	  // TODO In PieceStorage::cancelPiece(), WrDiskCacheEntry may be
292	  // released. Flush first.
293	  if (piece->getWrDiskCacheEntry()) {
294	    // Flush cached data here, because the cached data may be overlapped
295	    // if BT peers are involved.
296	    A2_LOG_DEBUG(fmt(
297	        "Flushing cached data, size=%lu",
298	        static_cast<unsigned long>(piece->getWrDiskCacheEntry()->getSize())));
299	    flushWrDiskCache(pieceStorage_->getWrDiskCache(), piece);
300	    // TODO Exception may cause some segments (pieces) are not
301	    // canceled.
302	  }
303	  piece->setUsedBySegment(false);
304	  pieceStorage_->cancelPiece(piece, cuid);
305	  segmentWrittenLengthMemo_[segment->getIndex()] = segment->getWrittenLength();
306	  A2_LOG_DEBUG(fmt("Memorized segment index=%lu, writtenLength=%" PRId64,
307	                   static_cast<unsigned long>(segment->getIndex()),
308	                   segment->getWrittenLength()));
309	}
