311	void SegmentMan::cancelSegment(cuid_t cuid)
312	{
313	  for (auto itr = usedSegmentEntries_.begin(), eoi = usedSegmentEntries_.end();
314	       itr != eoi;) {
315	    if ((*itr)->cuid == cuid) {
316	      cancelSegmentInternal(cuid, (*itr)->segment);
317	      itr = usedSegmentEntries_.erase(itr);
318	      eoi = usedSegmentEntries_.end();
319	    }
320	    else {
321	      ++itr;
322	    }
323	  }
324	}
325	
326	void SegmentMan::cancelSegment(cuid_t cuid,
327	                               const std::shared_ptr<Segment>& segment)
328	{
329	  for (auto itr = usedSegmentEntries_.begin(), eoi = usedSegmentEntries_.end();
330	       itr != eoi;) {
331	    if ((*itr)->cuid == cuid && *(*itr)->segment == *segment) {
332	      cancelSegmentInternal(cuid, (*itr)->segment);
333	      itr = usedSegmentEntries_.erase(itr);
334	      break;
335	    }
336	    else {
337	      ++itr;
338	    }
339	  }
340	}
