342	void SegmentMan::cancelAllSegments()
343	{
344	  for (auto& e : usedSegmentEntries_) {
345	    cancelSegmentInternal(e->cuid, e->segment);
346	  }
347	  usedSegmentEntries_.clear();
348	}
